        $this->table($f,'fee_setting_items',['fee_setting_id'=>['type'=>'INTEGER'],'item_code'=>['type'=>'VARCHAR','constraint'=>40],'item_name'=>['type'=>'VARCHAR','constraint'=>150],'amount'=>['type'=>'DECIMAL','constraint'=>'15,2'],'is_required'=>['type'=>'INTEGER'],'sort_order'=>['type'=>'INTEGER'],'created_at'=>['type'=>'DATETIME','null'=>true],'updated_at'=>['type'=>'DATETIME','null'=>true]]);
