    protected function tearDown():void{$f=Config\Database::forge('tests');foreach($this->tables() as $t)$f->dropTable($t,true);parent::tearDown();}
    public function testPageUsesAngularModal():void{$body=$this->admin()->get('/keuangan/tagihan')->getBody();$this->assertStringContainsString('ng-controller="tagihanMahasiswaController"',$body);$this->assertStringContainsString('id="billModal"',$body);$this->assertStringContainsString('Terbitkan tagihan',$body);}
    public function testCreateBillLocksFeeItems():void{$r=$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity,'due_date'=>'2026-10-01']);$r->assertStatus(201);$bill=$this->db->table('student_bills')->get()->getRowArray();$this->assertSame('150000',(string)(int)$bill['total_amount']);$this->assertSame('BELUM_DIBAYAR',$bill['status']);$this->assertCount(2,$this->db->table('student_bill_items')->where('student_bill_id',$bill['id'])->get()->getResultArray());}
    public function testDuplicateBillIsRejected():void{$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity])->assertStatus(201);$r=$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity]);$r->assertStatus(422);$this->assertStringContainsString('sudah memiliki tagihan',json_decode((string)$r->getJSON(),true)['message']);}
    public function testDueDateDefaultsToOneDayBeforeSchedule():void{$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity])->assertStatus(201);$this->assertSame('2026-09-09',$this->db->table('student_bills')->get()->getRow('due_date'));}
    public function testReadReturnsBillForActivePeriod():void{$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity])->assertStatus(201);$r=$this->admin()->get('/keuangan/tagihan/read');$r->assertStatus(200);$data=json_decode((string)$r->getJSON(),true)['data'];$this->assertCount(1,$data['bills']);$this->assertCount(0,$data['activities']);}
    public function testPreviewShowsRequiredAndOptionalComponents():void{$r=$this->admin()->get('/keuangan/tagihan/preview/'.$this->activity);$r->assertStatus(200);$items=json_decode((string)$r->getJSON(),true)['data']['items'];$this->assertCount(2,$items);$this->assertTrue($items[0]['is_required']);$this->assertFalse($items[1]['is_required']);}
    public function testOptionalComponentCanBeExcluded():void{$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity,'selected_item_ids'=>[$this->requiredItem]])->assertStatus(201);$bill=$this->db->table('student_bills')->get()->getRowArray();$this->assertSame(100000,(int)$bill['total_amount']);$this->assertSame(1,$this->db->table('student_bill_items')->where('student_bill_id',$bill['id'])->countAllResults());}
    public function testRequiredComponentCannotBeExcluded():void{$r=$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity,'selected_item_ids'=>[$this->optionalItem]]);$r->assertStatus(422);$this->assertStringContainsString('Komponen wajib tidak dapat dihilangkan',json_decode((string)$r->getJSON(),true)['message']);}
    public function testBillUsesFeeForSelectedExamPath():void{$this->db->table('exam_paths')->insert(['code'=>'JURNAL','name'=>'Jurnal','is_active'=>1,'sort_order'=>2]);$jurnal=(int)$this->db->insertID();$activity=$this->db->table('academic_activities')->where('id',$this->activity)->get()->getRowArray();$this->db->table('academic_activities')->where('id',$this->activity)->update(['exam_path_id'=>$jurnal]);$this->db->table('fee_settings')->insert(['academic_period_id'=>$activity['academic_period_id'],'study_program_id'=>$activity['study_program_id'],'activity_type_id'=>$activity['activity_type_id'],'exam_path_id'=>$jurnal,'version_no'=>1,'is_active'=>1]);$fee=(int)$this->db->insertID();$this->db->table('fee_setting_items')->insert(['fee_setting_id'=>$fee,'item_code'=>'JURNAL','item_name'=>'Tarif Jalur Jurnal','amount'=>275000,'is_required'=>1,'sort_order'=>1]);$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity])->assertStatus(201);$this->assertSame(275000,(int)$this->db->table('student_bills')->get()->getRow('total_amount'));$this->assertSame($jurnal,(int)$this->db->table('student_bills')->get()->getRow('exam_path_id'));}
    public function testCreatingBillAutomaticallyCreatesHonorEntitlement():void{$r=$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity]);$r->assertStatus(201);$payload=json_decode((string)$r->getJSON(),true);$this->assertSame(1,(int)$payload['data']['honor_entitlement_count']);$entitlement=$this->db->table('honor_entitlements')->get()->getRowArray();$this->assertSame('DIAJUKAN',$entitlement['status']);$this->assertSame(50000,(int)$entitlement['tax_amount']);$this->assertSame(950000,(int)$entitlement['net_amount']);}
    public function testMissingHonorRatePreventsBillForAssignedLecturer():void{$this->db->table('honor_rate_settings')->where('id >',0)->delete();$r=$this->mutation()->post('/keuangan/tagihan/post',['activity_id'=>$this->activity]);$r->assertStatus(422);$this->assertStringContainsString('Tarif honor untuk Dosen Uji',json_decode((string)$r->getJSON(),true)['message']);$this->assertSame(0,$this->db->table('student_bills')->countAllResults());}
    private function seed():void{$this->db->table('academic_years')->insert(['code'=>'2026/2027','name'=>'2026/2027','is_active'=>1]);$y=(int)$this->db->insertID();$this->db->table('academic_periods')->insert(['academic_year_id'=>$y,'semester_code'=>'GANJIL','is_active'=>1]);$this->period=(int)$this->db->insertID();$this->db->table('study_programs')->insert(['code'=>'TI','name'=>'Teknik Informatika','is_active'=>1]);$p=(int)$this->db->insertID();$this->db->table('activity_types')->insert(['code'=>'SEMINAR','name'=>'Seminar Proposal','is_active'=>1]);$a=(int)$this->db->insertID();$this->db->table('exam_paths')->insert(['code'=>'UMUM','name'=>'Umum','is_active'=>1,'sort_order'=>1]);$this->examPath=(int)$this->db->insertID();$this->db->table('students')->insert(['nim'=>'2026001','full_name'=>'Mahasiswa Uji','study_program_id'=>$p,'status'=>'AKTIF']);$s=(int)$this->db->insertID();$this->db->table('lecturers')->insert(['nidn'=>'001','full_name'=>'Dosen Uji','is_active'=>1]);$lecturer=(int)$this->db->insertID();$this->db->table('academic_activities')->insert(['activity_no'=>'KGT-001','student_id'=>$s,'academic_period_id'=>$this->period,'study_program_id'=>$p,'activity_type_id'=>$a,'exam_path_id'=>$this->examPath,'title'=>'Seminar','scheduled_at'=>'2026-09-10 09:00:00','status'=>'TERJADWAL']);$this->activity=(int)$this->db->insertID();$this->db->table('activity_assignments')->insert(['activity_id'=>$this->activity,'lecturer_id'=>$lecturer,'role_type'=>'PEMBIMBING','position_no'=>1,'status'=>'AKTIF']);$this->assignment=(int)$this->db->insertID();$this->db->table('honor_rate_settings')->insert(['academic_period_id'=>$this->period,'study_program_id'=>$p,'activity_type_id'=>$a,'role_type'=>'PEMBIMBING','position_no'=>1,'gross_amount'=>1000000,'tax_rate_percent'=>5,'version_no'=>1,'is_active'=>1]);$this->db->table('fee_settings')->insert(['academic_period_id'=>$this->period,'study_program_id'=>$p,'activity_type_id'=>$a,'exam_path_id'=>$this->examPath,'version_no'=>1,'is_active'=>1]);$fee=(int)$this->db->insertID();$this->db->table('fee_setting_items')->insert(['fee_setting_id'=>$fee,'item_code'=>'POKOK','item_name'=>'Tarif Pokok','amount'=>100000,'is_required'=>1,'sort_order'=>1]);$this->requiredItem=(int)$this->db->insertID();$this->db->table('fee_setting_items')->insert(['fee_setting_id'=>$fee,'item_code'=>'ADM','item_name'=>'Administrasi Opsional','amount'=>50000,'is_required'=>0,'sort_order'=>2]);$this->optionalItem=(int)$this->db->insertID();}
    private function tables():array{return['audit_logs','student_payment_allocations','student_payments','payment_methods','honor_entitlements','honor_rate_settings','activity_assignments','student_bill_items','student_bills','fee_setting_items','fee_settings','academic_activities','lecturers','students','exam_paths','activity_types','study_programs','academic_periods','academic_years'];}
    private function table($f,string $n,array $x):void{$f->addField(array_merge(['id'=>['type'=>'INTEGER','auto_increment'=>true]],$x));$f->addKey('id',true);$f->createTable($n);}private function auditTable($f):void{$this->table($f,'audit_logs',['user_id'=>['type'=>'INTEGER','null'=>true],'action'=>['type'=>'VARCHAR','constraint'=>100],'entity_type'=>['type'=>'VARCHAR','constraint'=>100],'entity_id'=>['type'=>'INTEGER'],'old_values'=>['type'=>'TEXT','null'=>true],'new_values'=>['type'=>'TEXT','null'=>true],'ip_address'=>['type'=>'VARCHAR','constraint'=>45,'null'=>true],'created_at'=>['type'=>'DATETIME','null'=>true]]);}private function admin():self{return$this->withSession(['auth'=>['id'=>1,'role'=>'ADMIN','username'=>'admin','full_name'=>'Admin']]);}private function mutation():self{helper('form');return$this->admin()->withHeaders([config('Security')->headerName=>csrf_hash()])->withBodyFormat('json');}
}
